-- Schede nuove dalle pagine RHS (controllo periodico del 23/11/2026): 28 specie del catalogo senza
-- nessuna scheda. Testi in italiano scritti a mano (scripts/rhs-import/dati/), in bozza e mostrate.
-- Generata da scripts/rhs-import/schede_nuove.py. Rollback: scripts/rhs-import/rollback_rhs_schede_nuove_lotto2.sql
do $$ begin
  if exists (select 1 from public.schede where taxon_id in ('8772b123-a611-453f-aeb0-012fb9e0fe81'::uuid, '6adb9e6b-16a0-45f8-a56d-02804e6cc35b'::uuid, 'fd787eae-43b5-4321-9c80-830b2e0b21ed'::uuid, '0569b733-7aee-48f0-a2f4-1d7868b993a1'::uuid, '06815242-698e-47c7-a459-98ea187a6074'::uuid, '0b671bb1-0dff-438c-866e-8d2e9f293073'::uuid, 'e281f7e4-eb88-4290-968a-26d91a7700c8'::uuid, '6bb3a6bb-5e6f-475a-9907-2859a43282e2'::uuid, '0ba5d614-7fe4-4506-b243-a93931e0c146'::uuid, '2fc96e62-99f7-4cad-b91a-7750790f3f0d'::uuid, 'fdb6b5cc-a44e-458b-8bcb-7f7b29a1070d'::uuid, '2dfe6b08-9cc9-42e9-ad0a-5954944af25a'::uuid, '7e8284a7-fa3b-4804-b640-6960051d2c86'::uuid, 'd439e20c-6009-40f2-bf78-bcf7d1913526'::uuid, 'fb904474-f46e-4e79-ac49-9f4777a798ca'::uuid, 'b08b49e3-fd12-48c0-899b-3ec69a7a2de5'::uuid, '90ea633c-14c3-4ce5-8831-c5921eb00ec4'::uuid, 'df4bd886-ae29-4696-96c1-93b31080339b'::uuid, 'bbdccead-0b3b-4930-b9a9-55c11a2fd51e'::uuid, '227d108d-add9-43ae-a95e-5f8cb62189fa'::uuid, 'd2f232b0-1687-413e-9ed8-e70945b70b4d'::uuid, '6e5a0e3c-b27a-4f34-9829-8bc2ba127158'::uuid, 'facf669e-ec25-45bc-a6b4-e667b2e18860'::uuid, 'bbabb968-31bb-47a6-a636-827b30cce2e9'::uuid, '13b3465e-33f0-482b-8027-9eecac766b4a'::uuid, 'df250b25-e197-4254-97e7-0143be08c60a'::uuid, '13b4be03-5b0f-4c80-9f50-2eca1bc1997d'::uuid, '47d8aeb4-812a-46a5-90ed-2df2c17de04d'::uuid)) then
    raise exception 'una di queste specie ha già una scheda: lotto da rigenerare';
  end if;
end $$;
insert into public.schede (id, taxon_id, fonti, descrizione, descrizione_originale, lingua_descrizione, esigenze,
  ciclo_vitale, alert, stato_verifica, mostrata, forma, nota) values
('8c4920d7-da4b-5945-869c-baf799d4ea74'::uuid, '8772b123-a611-453f-aeb0-012fb9e0fe81'::uuid, array['RHS (rhs.org.uk) — Berberis × hybridogagnepainii ''Jytte''']::text[], 'Arbusto sempreverde della famiglia delle Berberidacee, ibrido tra Berberis gagnepainii e Berberis verruculosa, fitto e spinoso, dal portamento a cuscino. Le foglie ovali, lucide e verde scuro, si arrossano in autunno; in primavera porta mazzetti di fiori penduli giallo oro, seguiti in autunno da bacche viola scuro. Si adatta a quasi tutti i terreni e alle posizioni più diverse, ma fiorisce e fruttifica meglio al sole; è adatto alle siepi basse e difensive.', 'A dense, spiny evergreen shrub with a mounding habit and oval-shaped, glossy green foliage, flushed red in autumn.  Clusters of drooping, golden-yellow flowers appear in spring, followed by dark purple berries in autumn', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ad afidi e alla tentredine del crespino; Malattie: può essere soggetto a oidio', 'Rusticità: minime anche sotto i -20 °C', 'Potatura: richiede pochi interventi: dopo la fioritura si accorciano i rami troppo lunghi e si tolgono quelli secchi o rovinati', 'Propagazione: per talee semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 203795'),
('1524b546-3def-5981-a78c-860e0748fb6b'::uuid, '6adb9e6b-16a0-45f8-a56d-02804e6cc35b'::uuid, array['RHS (rhs.org.uk) — Datura versicolor ''Grand Marnier''']::text[], 'Grande arbusto o piccolo albero della famiglia delle Solanacee, originario dell''Ecuador, che raggiunge i 4 m. Ha ampie foglie ellittiche e fiori a tromba penduli, lunghissimi, fino a 30-50 cm, che si aprono bianchi e virano al pesca, all''albicocca o al rosa, profumati soprattutto la sera. Teme il gelo: in vaso, d''estate all''aperto e d''inverno al riparo sopra i 5 °C, perde le foglie ma ricaccia in primavera. Tutte le parti della pianta sono velenose.', 'A large evergreen shrub or small tree to 4m, with large elliptic leaves and pendulous trumpet-shaped soft peach-pink flowers to 30cm in length, scented in the evening', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetta a ragnetto rosso, mosca bianca, tripidi e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 1.5-2.5m', 'Potatura: a fine inverno si accorciano i rami dell''anno prima fino a pochi occhi da una struttura di rami principali; se serve si riduce l''ingombro anche prima di ritirarla al riparo', 'Propagazione: per seme o per talee semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 31162'),
('b4583e1c-9f7f-5c38-9325-6bd08300ceaa'::uuid, 'fd787eae-43b5-4321-9c80-830b2e0b21ed'::uuid, array['RHS (rhs.org.uk) — Carex albula ''Amazon Mist''']::text[], 'Carice sempreverde della famiglia delle Ciperacee, originaria della Nuova Zelanda, che forma ciuffi alti circa 35 cm di foglie sottilissime, quasi capelli, arcuate e di un verde salvia argentato. A metà e a fine estate porta piccole spighe brune su steli sottili. Si usa per dare movimento ai bordi, ai giardini di ghiaia e ai vasi; vuole terreno fertile, fresco ma ben drenato, e una posizione riparata, al sole o in mezz''ombra, lontano dagli eccessi di secco e di umidità.', 'Clump-forming, evergreen perennial sedge, about 35cm tall, with arching, hair-like, silvery sage-green leaves. Carries brown flower spikes on wiry stems, 25cm long in mid and late summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso, argilloso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.5-1m', 'Potatura: in estate si tolgono le foglie secche, pettinandole con le dita', 'Propagazione: per divisione da metà primavera a inizio estate']::text[], 'bozza', true, 'graminacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 241877'),
('7d9e401b-41b5-5025-a212-9dde1b568692'::uuid, '0569b733-7aee-48f0-a2f4-1d7868b993a1'::uuid, array['RHS (rhs.org.uk) — Cistus × corbariensis']::text[], 'Cisto ibrido della famiglia delle Cistacee, nato spontaneamente nell''Europa meridionale dall''incrocio tra Cistus populifolius e Cistus salviifolius, conosciuto anche come Cistus × hybridus. Forma un arbusto sempreverde fitto e tondeggiante, alto circa un metro e più largo che alto, con foglie ondulate e rugose. In estate si copre di fiori bianchi con il centro giallo, che spuntano da boccioli rossi e durano un solo giorno, rinnovandosi a lungo. Ama il sole pieno e i terreni poveri e sciolti.', 'A bushy, dense, evergreen shrub to 1m tall with wavy-edged and wrinkled leaves.White flowers with yellow centres are freely produced in summer emerging from red buds', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 1-1.5m', 'Potatura: dopo la fioritura si cimano i rami giovani per renderlo più compatto; non sopporta i tagli drastici, e gli esemplari vecchi e spogli conviene sostituirli', 'Propagazione: per talee erbacee o semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 94293'),
('65a994fa-b58a-5059-ba1f-9728e601ca34'::uuid, '06815242-698e-47c7-a459-98ea187a6074'::uuid, array['RHS (rhs.org.uk) — Clematis × jouiniana ''Praecox''']::text[], 'Clematide ibrida della famiglia delle Ranuncolacee, nata dall''incrocio tra Clematis heracleifolia e Clematis vitalba. Più che arrampicarsi si distende: i lunghi fusti semilegnosi, fino a 3-4 m, si appoggiano agli arbusti vicini o ricadono dai muretti, con foglie pennate e grossolanamente dentate. Da metà estate all''inizio dell''autunno si copre di una profusione di piccoli fiori, larghi 2 cm, con quattro sepali ripiegati, bianco latte sfumati di azzurro. Vuole le radici al fresco e all''ombra e la chioma al sole.', 'A deciduous herbaceous sub-shrub with long scrambling stems bearing pinnate, strongly toothed leaves. Abundant, 2cm in width flowers with four recurved, pale milky-blue sepals from midsummer to early autumn', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, chiocciole e bruchi; le forbicine possono mangiare i petali; Malattie: può essere soggetta ad avvizzimento della clematide, flusso mucoso e, raramente, armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 1.5-2.5m', 'Potatura: a fine inverno si tagliano tutti i fusti a 20-30 cm da terra, sopra una coppia di gemme robuste: fiorisce sui rami nuovi', 'Propagazione: per propaggine, per divisione o per talee basali']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 68369'),
('2549592b-bf77-5faa-af7e-8d1025272205'::uuid, '0b671bb1-0dff-438c-866e-8d2e9f293073'::uuid, array['RHS (rhs.org.uk) — Coleonema pulchrum ''Golden Sunset''']::text[], 'Arbusto sempreverde della famiglia delle Rutacee, originario della provincia del Capo in Sudafrica, alto fino a 1,5 m. Molto ramificato, prima eretto e poi espanso, ha foglie sottilissime, quasi aghiformi, che strofinate liberano un profumo aromatico; dalla tarda primavera all''estate si copre di piccoli fiori a stella rosa, o bianchi in alcune forme, mentre la varietà ''Sunset Gold'' è coltivata per il fogliame giallo dorato. Vuole sole, terreno sciolto senza calcare e riparo dal gelo.', 'a free-branching shrub, upright then spreading with fine, narrow, bright yellow-green leaves 2-4cm long. It bears white flowers around 1cm acrossfrom late spring to summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto a marciume radicale da Phytophthora', 'Rusticità: minime fino a -5 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 1-1.5m', 'Potatura: dopo la fioritura si accorciano leggermente i rami per mantenerlo compatto', 'Propagazione: per seme in superficie a 13-16 °C in primavera o per talee semilegnose con calore dal fondo in estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 140335'),
('d6da75c0-a1c0-506c-9a6c-b927ad3d6a33'::uuid, 'e281f7e4-eb88-4290-968a-26d91a7700c8'::uuid, array['RHS (rhs.org.uk) — Corydalis quantmeyeriana ''Chocolate Star''']::text[], 'Perenne della famiglia delle Papaveracee, originaria della Cina occidentale, che forma cuscini alti fino a 40 cm di foglie finemente divise in foglioline ovali e smerlate. Il fogliame cambia colore con le stagioni: bruno rossastro in autunno e in inverno, bronzato in primavera, verde oliva d''estate. In primavera porta su steli eretti racemi di fiori tubolari e speronati, lilla rosati. Vuole mezz''ombra e terreno ricco di humus, come nel sottobosco.', 'A mounding, evergreen perennial to 40cm high with leaves divided into ovate, scallop-edged leaflets. Foliage is a reddish-brown in autumn and winter with bronze tints in spring and shading to olive green in late spring and summer. Slender, tubular, lilac-pink flowers are borne on upright stems above the leaves in spring', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 242408'),
('cc50bc9e-635a-5e04-a577-58a1c1a02f18'::uuid, '6bb3a6bb-5e6f-475a-9907-2859a43282e2'::uuid, array['RHS (rhs.org.uk) — Potentilla davurica ''Abbotswood''']::text[], 'Arbusto deciduo della famiglia delle Rosacee, diffuso dalla Siberia alla Cina, a lungo considerato una varietà della comune potentilla arbustiva. Cespuglioso e fitto, alto per lo più meno di un metro, ha piccole foglie pennate verde scuro divise in cinque foglioline e, dalla tarda primavera fino all''autunno, una lunga successione di fiori bianchi a cinque petali, larghi 3-4 cm. Rustica e di poche pretese, cresce in quasi ogni terreno; i fiori durano di più dove il suolo resta un po'' fresco e il sole non è troppo forte.', 'A bushy deciduous shrub to 75cm, the small, dark green, pinnate leaves with 5 leaflets. Flowers white, 4cm in width, over a long season from late spring', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: a fine inverno si accorciano i rami dell''anno prima e si tolgono quelli vecchi o deboli, per tenerla compatta e fiorita', 'Propagazione: per talee erbacee a inizio estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 120502'),
('e95ff857-af8b-5519-9fc5-07edb667154e'::uuid, '0ba5d614-7fe4-4506-b243-a93931e0c146'::uuid, array['RHS (rhs.org.uk) — Erigeron speciosus ''Azurfee''']::text[], 'Perenne della famiglia delle Asteracee, originaria dell''America settentrionale occidentale, che forma cespi alti 45-60 cm di foglie lanceolate. Da inizio a fine estate porta su steli sottili capolini simili a margherite, con numerose ligule sottili viola, lilla o rosa intorno al centro giallo; molte varietà hanno fiori semidoppi. Vuole terreno fertile e ben drenato che non si secchi d''estate, il sole o una leggera ombra nelle ore più calde.', 'A clump-forming perennial to around 45cm high, with lance-shaped green leaves. Daisy-like, semi-double flowers, with violet-blue petals and yellow centres, are borne on wiry stems from early to late summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta a oidio', 'Rusticità: minime fino a -20 °C', 'Potatura: in autunno o a inizio primavera si tagliano gli steli fino ai nuovi getti vicino a terra', 'Propagazione: per seme o per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 208784'),
('e1e584b5-0866-5723-97fd-095b8a9de166'::uuid, '2fc96e62-99f7-4cad-b91a-7750790f3f0d'::uuid, array['RHS (rhs.org.uk) — Forsythia koreana ''Kumson''']::text[], 'Arbusto deciduo della famiglia delle Oleacee, originario della Corea, vicino alla forsizia comune dei nostri giardini. Ha rami eretti e arcuati e foglie semplici, verde vivo, che in autunno si tingono di porpora; a fine inverno e in primavera, prima delle foglie, si copre di fiori gialli a campanella con quattro lobi aperti. È la madre di varietà ornamentali come ''Kumson'', dalle foglie con le nervature segnate di bianco argento. Facile e rustico, vuole sole o mezz''ombra e terreno fresco.', 'A compact, bushy deciduous shrub, up to 1.5m high and wide, with unusual variegated leaves where the veins are marked silver grey creating a delicate pattern on the green leaves which turn purple in autumn. The yellow flowers are borne before the foliage late spring', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: gli uccelli possono beccare i boccioli; Malattie: può essere soggetto ad armillaria e alle galle della forsizia', 'Rusticità: minime fino a -15 °C', 'Potatura: subito dopo la fioritura si accorciano i rami che hanno fiorito fino a un germoglio robusto e ogni anno si toglie alla base qualche ramo vecchio per rinnovare l''arbusto', 'Propagazione: per talee semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 253703'),
('1b89154b-8b28-5201-8b37-ce3cd72cf302'::uuid, 'fdb6b5cc-a44e-458b-8bcb-7f7b29a1070d'::uuid, array['RHS (rhs.org.uk) — Geranium sessiliflorum subsp. novae-zelandiae red-leaved']::text[], 'Piccolo geranio perenne della famiglia delle Geraniacee, originario della Nuova Zelanda, dell''Australia e del Sud America. Forma cuscinetti bassi, di circa 15 cm, di foglie rotonde e lobate, che nelle forme più coltivate sono di un bel bronzo rossastro; in estate vi spuntano piccoli fiori bianchi che risaltano sul fogliame scuro. Sempreverde, adatto ai giardini rocciosi, ai bordi e ai vasi, dà il colore migliore in pieno sole.', 'A small mound-forming perennial, to around 15cm high, with rounded, lobed reddish-bronze leaves. Small white flowers are produced in summer, standing out against the dark foliage', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a larve di oziorrinco, tentredini del geranio, miridi, lumache e limacce; Malattie: può essere soggetto a peronospora e virosi, e a oidio con il secco', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: si tolgono gli steli sfioriti e le foglie vecchie per favorire la nuova vegetazione', 'Propagazione: per divisione in primavera o per talee basali a inizio primavera, con calore dal fondo']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 56435'),
('be847980-d0b9-5d13-ad39-46d43ad960b5'::uuid, '2dfe6b08-9cc9-42e9-ad0a-5954944af25a'::uuid, array['RHS (rhs.org.uk) — Hedera canariensis ''Aurea''']::text[], 'Edera sempreverde della famiglia delle Araliacee, originaria delle Canarie, vigorosa e capace di arrampicarsi da sola fino a 10 m grazie alle radici aeree. Ha foglie grandi, coriacee, poco lobate, su fusti rossastri; se ne coltivano anche forme variegate di crema e di bianco. Sulle parti adulte porta ombrelle di piccoli fiori verdastri seguiti da bacche nere. Cresce in quasi tutti i terreni ma preferisce una posizione riparata: è meno rustica della nostra edera comune.', 'Vigorous, large, self-clinging, evergreen climber about 10m tall, with large, shallowly 5-lobed, matt green or yellowish-green leaves, sometimes unevenly variegated or irregularly spotted with cream or white, or half green, half white. Small greenish flowers in umbels are followed by black berries', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a ragnetto rosso, cocciniglie, oziorrinco e afidi; Malattie: può essere soggetta a maculature fogliari e, raramente, ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 8-12m, diffusione 4-8m', 'Potatura: si può accorciare in qualsiasi momento dell''anno per contenerla, tagliando i fusti che escono dallo spazio voluto e quelli che si staccano dal supporto', 'Propagazione: per talee erbacee in qualsiasi momento, talee semilegnose o legnose da fine estate a fine inverno, per propaggine o per innesto']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 370506'),
('d0e3ddb2-15e1-5330-ac42-eab29c7b48d7'::uuid, '7e8284a7-fa3b-4804-b640-6960051d2c86'::uuid, array['RHS (rhs.org.uk) — Hepatica japonica var. nipponica f. magna soft pink-flowered, marbled leaf']::text[], 'Piccola perenne della famiglia delle Ranuncolacee, originaria dei boschi del Giappone, sorella dell''erba trinità dei nostri boschi. Cresce lenta in ciuffi alti meno di 10 cm, con foglie coriacee e lobate, verde scuro, spesso marmorizzate o bronzate, che restano quasi tutto l''anno. Da fine inverno a inizio primavera porta fiori delicati con sei-otto petali, bianchi, rosa, rossi o viola, con stami dello stesso colore o in contrasto: in Giappone ne vengono coltivate da secoli centinaia di forme, alcune a fiore doppio. Vuole mezz''ombra e terreno ricco di humus.', 'A small, slow-growing, semi-evergreen perennial to 8cm with leathery, lobed, dark green leaves which may be marbled or bronzed. Small, delicate flowers with six to eight petals appear in late winter to early spring and may be white, pink, red or purple, with matching or contrasting stamens', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; in autunno si sparge sul terreno uno strato di terriccio di foglie', 'Propagazione: per seme appena maturo, in cassone all''aperto, o per divisione in primavera; le piante divise o trapiantate attecchiscono lentamente']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 544576'),
('1c9d43a2-9f91-553f-b2c5-aa7dc1650aee'::uuid, 'd439e20c-6009-40f2-bf78-bcf7d1913526'::uuid, array['RHS (rhs.org.uk) — Hesperocyparis glabra ''Angaston''']::text[], 'Conifera sempreverde della famiglia delle Cupressacee, originaria delle montagne aride dell''Arizona, conosciuta a lungo come cipresso dell''Arizona (Cupressus arizonica var. glabra). Forma un albero conico e regolare che supera i 10 m, con fogliame squamoso grigio-azzurro, quasi argentato, e una corteccia liscia rosso porpora che si stacca in placche sottili. Cresce in fretta, sopporta bene la siccità e il caldo e vuole pieno sole e terreno ben drenato; ne esistono forme nane, colonnari e piangenti molto usate nei giardini.', 'A unique, fast-growing evergreen conifer with a curious weeping habit, blue-green foliage giving a ''smokey'' effect and reddish brown, peeling bark. A specimen tree that can become a living sculpture', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie, ma può essere soggetto ad armillaria', 'Rusticità: minime fino a -15 °C', 'Potatura: non richiede potatura', 'Propagazione: per seme o per talee semilegnose']::text[], 'bozza', true, 'conifera', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 544861'),
('08d553d9-928d-559d-92fb-3479f8dfd94d'::uuid, 'fb904474-f46e-4e79-ac49-9f4777a798ca'::uuid, array['RHS (rhs.org.uk) — Hypericum polyphyllum ''Grandiflorum''']::text[], 'Suffrutice nano della famiglia delle Ipericacee, originario delle montagne della Turchia meridionale, alto appena 20 cm. Forma un cuscinetto ordinato di foglioline grigio-verdi e, da metà a fine estate, porta in cima ai fusti fiori giallo vivo con un ciuffo centrale di stami dorati. Adatto ai giardini rocciosi e ai vasi da roccaglia, vuole pieno sole e terreno ben drenato e teme l''umidità invernale.', 'A dwarf sub-shrub to 20cm tall, forming a neat mound of grey-green leaves. From mid- to late summer, at the stem tips, it produces bright yellow flowers with a central tuft of golden yellow stamens. Well suited to a rock garden or alpine trough', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto a ruggine e, raramente, ad armillaria', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: richiede pochi interventi: a inizio primavera si accorciano i fusti per tenerlo compatto e si tolgono quelli secchi o rovinati', 'Propagazione: per talee erbacee o semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 56461'),
('c644562f-dabe-5892-97ec-c85f6ce9ed04'::uuid, 'b08b49e3-fd12-48c0-899b-3ec69a7a2de5'::uuid, array['RHS (rhs.org.uk) — Malus × gloriosa ''Golden Gem''']::text[], 'Melo da fiore della famiglia delle Rosacee, ibrido ottenuto in Germania nel Novecento, piccolo albero deciduo a chioma tondeggiante che non supera i 4 m. In tarda primavera si copre di mazzetti fitti di fiori bianchi, profumati, a cui seguono piccoli frutti decorativi, gialli o rossi a seconda della varietà, che restano a lungo sui rami e attirano gli uccelli. Vuole sole e un terreno mediamente fertile.', 'A small tree to about 4m, with a rounded crown. Strongly scented, pure white flowers are produced in dense clusters in late spring, followed by pea-sized, yellow fruit', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ad afidi, compreso l''afide lanigero, ragnetto rosso dei fruttiferi e bruchi; Malattie: può essere soggetto a cancro, ticchiolatura, moniliosi, colpo di fuoco, armillaria e oidio', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 2.5-4m', 'Potatura: richiede pochi interventi: in inverno si tolgono solo i rami secchi, rovinati, incrociati o i polloni', 'Propagazione: per innesto a gemma a fine estate o per innesto a marza a metà inverno']::text[], 'bozza', true, 'albero', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 254021'),
('64db9a63-38b8-50f4-adfa-d5242277ef36'::uuid, '90ea633c-14c3-4ce5-8831-c5921eb00ec4'::uuid, array['RHS (rhs.org.uk) — Meconopsis × sheldonii Crewdson hybrids']::text[], 'Ibrido della famiglia delle Papaveracee nato dall''incrocio tra Meconopsis grandis e Meconopsis betonicifolia, i celebri papaveri blu dell''Himalaya. Forma rosette di foglie oblunghe, pelose e appena dentate, da cui in estate si alzano steli fino a 1,5 m con fiori a coppa, un po'' penduli, di un azzurro limpido e intenso, dai petali ondulati. Alle corolle seguono capsule ispide e decorative che però non danno semi fertili. Pianta esigente: ama le estati fresche e umide, il terreno ricco di humus e una mezz''ombra riparata dal vento, e spesso vive pochi anni.', 'A bushy, often short-lived, perennial to 1.5m tall, forming basal rosettes of oblong to lanceolate leaves with shallow teeth. The rich, clear blue, slightly-nodding, cup-shaped flowers, borne in summer, comprise wavy-edged elliptical petals, longer than they are broad, and are followed by decorative capsules covered in bristles but containing no viable seed', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: può essere soggetta a peronospora', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 0.1-0.5m', 'Potatura: a fine autunno si tagliano gli steli alla base', 'Propagazione: per divisione dei cespi dopo la fioritura']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 90461'),
('6e5d7328-b8ee-59aa-91ae-9eeae56af5aa'::uuid, 'df4bd886-ae29-4696-96c1-93b31080339b'::uuid, array['RHS (rhs.org.uk) — Oenothera tetragona']::text[], 'Perenne erbacea della famiglia delle Onagracee, originaria dell''America settentrionale orientale, alta fino a 80 cm. Gli steli eretti portano foglie ovali, lisce e glauche, rossastre da giovani, e terminano in racemi di fiori giallo chiaro a coppa, larghi 3-5 cm, che si aprono di giorno dalla tarda primavera fino a fine estate. Ama il pieno sole e i terreni ben drenati, anche poveri e calcarei, e si presta alle bordure e ai giardini di gusto mediterraneo.', 'An herbaceous perennial to 80cm, with erect stems bearing smooth, ovate, glaucous leaves, reddish when young, and terminal racemes of light yellow flowers 3-5cm wide from late spring to late summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: lumache e limacce possono danneggiarla; Malattie: può essere soggetta a maculature fogliari e oidio', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura si tagliano gli steli sfioriti', 'Propagazione: per divisione a inizio primavera o a fine estate, dopo la fioritura']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 25533'),
('03e4741a-b37f-5756-8f69-8af63f25c67c'::uuid, 'bbdccead-0b3b-4930-b9a9-55c11a2fd51e'::uuid, array['RHS (rhs.org.uk) — Philadelphus × lemoinei']::text[], 'Arbusto deciduo della famiglia delle Idrangeacee, ottenuto in Francia alla fine dell''Ottocento incrociando Philadelphus coronarius e Philadelphus microphyllus. Compatto ed eretto, alto fino a 1,5 m, ha foglie verde chiaro e tra maggio e giugno si copre di fiori bianchi aperti, con gli stami giallo vivo, dal profumo dolce che ricorda quello dei fiori d''arancio, da cui il nome di fiore d''angelo o falso gelsomino con cui sono noti i suoi parenti. Si adatta a quasi tutti i terreni, purché non ristagni l''acqua.', 'A compact, upright, deciduous shrub with light green foliage and a profusion of sweet scented, open, white blooms with bright yellow stamen in summer from May to June', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, argilloso, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ad afidi; Malattie: può essere soggetto a oidio e, raramente, ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 1-1.5m', 'Potatura: subito dopo la fioritura si accorciano i rami che hanno fiorito fino a un germoglio robusto e ogni anno si toglie alla base qualche ramo vecchio, circa uno su cinque, per rinnovare la pianta', 'Propagazione: per talee erbacee in estate o legnose in inverno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 94392'),
('619f89f8-53b2-50aa-ac92-0edd0f987d74'::uuid, '227d108d-add9-43ae-a95e-5f8cb62189fa'::uuid, array['RHS (rhs.org.uk) — Primula × pruhoniciana ''Lady Greer''']::text[], 'Primula ibrida della famiglia delle Primulacee, nata all''inizio del Novecento a Průhonice, in Boemia, dall''incrocio tra Primula juliae e la primula comune. Molto rustica e sempreverde, forma piccole rosette di foglie verde scuro da cui, da metà inverno a inizio primavera, spuntano fiori piatti, spesso profumati, bianchi, crema, rosa, porpora o rossi, singoli o riuniti in ombrelle. Ama la mezz''ombra e il terreno fresco e ricco di humus.', 'A very hardy, rosette-forming evergreen perennial with dark green foliage and small, fragrant cream flowers, flushed with pink as they mature, appearing mid winter to early spring', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, oziorrinco, lumache, nematodi, minatori fogliari e ragnetto rosso; Malattie: può essere soggetta a maculatura fogliare, marciume del colletto e muffa grigia', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione in autunno o dopo la fioritura']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 113807'),
('1f335451-c2fc-5573-b718-e7cbcfc1e36e'::uuid, 'd2f232b0-1687-413e-9ed8-e70945b70b4d'::uuid, array['RHS (rhs.org.uk) — Rhododendron × loderi']::text[], 'Rododendro ibrido della famiglia delle Ericacee, ottenuto all''inizio del Novecento incrociando Rhododendron griffithianum e Rhododendron fortunei. Forma grandi arbusti sempreverdi che con gli anni diventano quasi alberi, con lunghe foglie verde scuro. A maggio porta grandi grappoli di fiori a imbuto, profumatissimi, dal bianco puro al crema e a varie sfumature di rosa. Vuole terreno acido, fresco e ricco di humus, mezz''ombra e riparo dal vento.', 'A group of large, hardy, evergreen shrubs, which can reach tree-like heights, with long, dark green leaves.  Clusters of fragrant flowers range from pure white to creamy shades of pink and darker pink appear in May', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a oziorrinco, mosca bianca e cicalina del rododendro, tingide, cocciniglie, bruchi e afidi; Malattie: può essere soggetto a oidio, avvizzimento dei petali, disseccamento delle gemme, mal del piombo e armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 2.5-4m', 'Potatura: richiede pochi interventi: dopo la fioritura si tolgono i fiori appassiti, senza rovinare le gemme sottostanti, e i rami secchi o rovinati', 'Propagazione: per talee semilegnose a fine estate, per propaggine in autunno o per innesto a fine estate o a fine inverno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 138863'),
('e97e8bcd-5113-5b3b-b218-bd57811fd76d'::uuid, '6e5a0e3c-b27a-4f34-9829-8bc2ba127158'::uuid, array['RHS (rhs.org.uk) — Rosa × borboniana ''Madame Ernest Calvat''']::text[], 'Rosa ibrida della famiglia delle Rosacee, nata all''inizio dell''Ottocento sull''isola di Bourbon, oggi La Riunione, da un incrocio spontaneo tra la rosa di Damasco e la rosa cinese. Da essa discendono le rose Bourbon, arbusti vigorosi alti fino a 2 m, con rami arcuati e foglie verde scuro, che portano grandi fiori stradoppi, spesso appiattiti e divisi in quarti, rosa, cremisi o bianchi, dal profumo intenso. Rifioriscono dall''estate all''autunno e alcune varietà fioriscono bene anche a mezz''ombra.', 'Large, bushy, old-fashioned rose about 1.5-1.8m tall, a sport of ''Mme Isaac Pereire'', with arching stems carrying dark green leaves. Large, cabbage-like, flat, quartered blooms in shades of pale pink with yellow anthers, have a powerful fragrance, repeat-flowers through summer to autumn and does well in the shade; introduced in 1888', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, cicaline, ragnetto rosso, cocciniglie, bruchi e tentredini; cervi e conigli possono danneggiarla; Malattie: può essere soggetta a ticchiolatura, ruggine, oidio, disseccamento dei rami e stanchezza del terreno, talvolta ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 1-1.5m', 'Potatura: a fine inverno si accorciano di un terzo i rami principali e si tolgono quelli secchi, deboli o malati; i rami più vecchi si possono tagliare alla base per rinnovare l''arbusto', 'Propagazione: per talee legnose in autunno, per talee erbacee in primavera o in estate al riparo, oppure per innesto a gemma in estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 225263'),
('9accb4fd-cf3e-5cc9-a5b5-74a5e86098bb'::uuid, 'facf669e-ec25-45bc-a6b4-e667b2e18860'::uuid, array['RHS (rhs.org.uk) — Rosa hugonis']::text[], 'Rosa botanica della famiglia delle Rosacee, originaria della Cina, introdotta nei giardini alla fine dell''Ottocento con il nome del missionario che ne mandò i semi in Europa. Vigorosa, alta fino a 2,5 m, ha rami arcuati bruno scuro e spinosi e un fogliame fine, quasi da felce, che in autunno si tinge di bronzo e arancio. In tarda primavera si copre di fiori semplici a coppa, larghi 5 cm, da crema a giallo primula, leggermente profumati, seguiti da piccole bacche bruno rossastre. Rustica e poco esigente, è adatta anche alle siepi libere.', 'A vigorous shrub to about 2.5m tall, with fern-like foliage turning bronzy-orange in autumn, on arching deep brown, thorny stems, and bearing abundant, slightly fragrant, cupped, single creamy to primrose-yellow flowers 5cm in width in late spring, followed by small red-brown fruits (hips)', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, cicaline, ragnetto rosso, cocciniglie, bruchi e tentredini; conigli e cervi possono danneggiarla; Malattie: può essere soggetta a ticchiolatura, ruggine, oidio, disseccamento dei rami, stanchezza del terreno e talvolta armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 1.5-2.5m', 'Potatura: fiorisce sui rami dell''anno prima: subito dopo la fioritura si tolgono solo i rami vecchi, secchi o rovinati, a meno che non si vogliano lasciare le bacche', 'Propagazione: per talee legnose in autunno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 16044'),
('9509793c-18d3-53e6-9389-e9f1d0d14a97'::uuid, 'bbabb968-31bb-47a6-a636-827b30cce2e9'::uuid, array['RHS (rhs.org.uk) — Santolina neapolitana']::text[], 'Suffrutice sempreverde e aromatico della famiglia delle Asteracee, endemico dell''Italia meridionale, dove cresce sulle rupi calcaree. Forma cuscini di 30-50 cm di foglie grigio-verdi, finemente divise, e in estate porta su lunghi steli capolini a bottone giallo limone, larghi circa 2 cm. Ama il caldo, il sole e i terreni ben drenati; si presta alle bordure basse e ai giardini di ghiaia, ma tende a spogliarsi con gli anni.', 'An aromatic dwarf evergreen shrub with small, finely divided grey-green leaves and abundant long-stalked, bright lemon-yellow, button-like flowers heads 2cm in width', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.5-1m', 'Potatura: dopo la fioritura si accorcia tutta la pianta tagliando gli steli fioriti, per mantenerla densa e compatta; in primavera si possono spuntare i fusti, senza tagliare nel legno vecchio', 'Propagazione: per seme in autunno, in piena terra o in contenitore, o per talee semilegnose a fine estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 232166'),
('feaf2be8-a179-5a7b-85ef-363ee8a1f514'::uuid, '13b3465e-33f0-482b-8027-9eecac766b4a'::uuid, array['RHS (rhs.org.uk) — Sedum mexicanum ''Lemon Ball''']::text[], 'Succulenta perenne della famiglia delle Crassulacee, originaria del Messico, che forma tappeti bassi, sotto i 10 cm, di fusti striscianti che radicano a terra. Le foglie carnose, sottili come aghi, sono fitte e di un verde giallastro brillante, che nella varietà ''Lemon Ball'' diventa giallo limone. In estate porta mazzetti di piccoli fiori gialli a stella. Vuole pieno sole, terreno ben drenato e una posizione riparata: teme il gelo intenso e l''umidità invernale.', 'A mound-forming, succulent perennial to 10cm tall, with fleshy, needle-like, vibrant yellow-green leaves densely packed on trailing, rooting stems. In summer it produces clusters of small, starry yellow flowers above the foliage', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta a marciumi del colletto e delle radici', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per talee di fusto']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 350044'),
('433f80bf-1863-5100-b206-4f66b3eb548d'::uuid, 'df250b25-e197-4254-97e7-0143be08c60a'::uuid, array['RHS (rhs.org.uk) — Sorbus × arnoldiana ''Apricot Queen''']::text[], 'Piccolo albero deciduo della famiglia delle Rosacee, ibrido nato all''Arnold Arboretum di Boston, che arriva a circa 6 m in vent''anni. Ha portamento eretto, poi espanso, e foglie verde scuro divise in coppie di foglioline dentate, che in autunno si accendono di arancio e di rosso. In primavera porta corimbi di fiori bianchi, seguiti da bacche gialle, aranciate o rosate, a seconda della varietà, che restano sui rami fino all''inverno e attirano gli uccelli.', 'A deciduous tree, to around 6m in 20 years, with an upright to spreading habit, and deep green leaves divided into pairs of toothed leaflets. Leaves turn shades of orange and red in autumn. Clusters of white spring flowers are followed by golden orange berries that persist into the winter months', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ad afidi, cocciniglie, eriofidi, ragnetto rosso e larve di tentredini; Malattie: può essere soggetto a colpo di fuoco, cancro, mal del piombo e armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 4-8m, diffusione 2.5-4m', 'Potatura: richiede pochi interventi: si tolgono solo i rami secchi, rovinati o mal disposti, a fine inverno', 'Propagazione: per talee erbacee o per innesto']::text[], 'bozza', true, 'albero', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 103934'),
('4bafb085-2bf5-5617-8a4c-d70d209664eb'::uuid, '13b4be03-5b0f-4c80-9f50-2eca1bc1997d'::uuid, array['RHS (rhs.org.uk) — Spiranthes cernua var. odorata ''Chadd''s Ford''']::text[], 'Orchidea terrestre della famiglia delle Orchidacee, originaria delle zone umide degli Stati Uniti sudorientali, nota a lungo come Spiranthes cernua var. odorata. Forma cespi di foglie strette e lineari e, da fine estate all''autunno, alza spighe fino a 60 cm su cui piccoli fiori bianchi, con una macchia gialla sul labello, sono disposti a spirale come una treccia. Il profumo è intenso e ricorda la vaniglia e il gelsomino. Vuole terreno fresco, ricco di humus, e mezz''ombra riparata; nelle zone fredde si protegge d''inverno con una pacciamatura spessa e asciutta.', 'A clump-forming terrestrial orchid to 60cm tall with broadly linear leaves to 20cm long and a plentiful number of white flowers, scented of vanilla and jasmine, about 1cm long with a yellow mark on the lip, arranged spirally on spikes to 65cm tall, appearing from late summer until autumn', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco; pH neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetta ad afidi e ragnetto rosso; Malattie: generalmente resistente alle malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione dei tuberi a riposo; d''inverno si formano piantine sulla punta delle radici, che si staccano quando sono abbastanza grandi']::text[], 'bozza', true, 'orchidea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 115251'),
('8e91dfc8-926c-507c-94a3-b1afe257150e'::uuid, '47d8aeb4-812a-46a5-90ed-2df2c17de04d'::uuid, array['RHS (rhs.org.uk) — Veronica teucrium']::text[], 'Perenne erbacea della famiglia delle Plantaginacee, diffusa in gran parte dell''Europa, anche nei prati aridi e ai margini dei boschi d''Italia. Forma cespi alti fino a 60 cm, con foglie oblunghe, dentate e pelose, e all''inizio dell''estate porta spighe di piccoli fiori piatti di un azzurro intenso, rivolti verso l''esterno. Robusta e facile, cresce in quasi ogni terreno fertile, al sole o in mezz''ombra.', 'A clump-forming perennial to 60cm tall with oblong, toothed, hairy leaves and spikes of small, flat, outward-facing, bright blue flowers in the summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi; Malattie: può essere soggetta a peronospora, maculature fogliari, marciumi, Phytophthora e talvolta armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: si tolgono i fiori appassiti e a inizio autunno, quando il fogliame si sciupa, si taglia la pianta alla base', 'Propagazione: per divisione in autunno o in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 93363');
